<script setup lang="ts">
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { logout as apiLogout } from '@/api/auth'
import { useAuthStore } from '@/stores/auth'
import { useAssessmentStore } from '@/stores/assessments'
import { beijingDate } from '@/utils/formatters'
const router=useRouter(),route=useRoute(),auth=useAuthStore(),assessments=useAssessmentStore()
const isListPage=computed(()=>route.path==='/assessments')
// 日期分桶按北京时间（表格展示时区一致）；按 UTC 切会在 16:00 后错一天
const dates=computed(()=>{const groups=new Map<string,number>();assessments.records.forEach(item=>{const date=beijingDate(item.created_at);groups.set(date,(groups.get(date)||0)+1)});return [...groups.entries()].sort(([a],[b])=>b.localeCompare(a)).map(([date,count])=>({date,count}))})
const statusCount=(value:'all'|'pending'|'viewed')=>value==='all'?assessments.records.length:assessments.records.filter(item=>assessments.reviewState(item)===value).length
function selectAll(){assessments.dateFilter='all';assessments.reviewFilter='all'}
async function logout(){try{await apiLogout()}catch{/* 服务端会话已失效也继续本地退出 */}auth.clear();router.replace('/login')}
</script>
<template><div class="admin-shell"><aside class="sidebar"><div class="brand"><div class="brand__mark">AI</div><div><strong>AI视觉心理评估终端</strong><span>管理与报告中心</span></div></div><nav class="side-nav"><RouterLink to="/assessments">测评报告</RouterLink><RouterLink to="/appointments">社区预约</RouterLink></nav><template v-if="isListPage"><section class="sidebar-filters"><button class="sidebar-filter sidebar-filter--all" :class="{active:assessments.dateFilter==='all'&&assessments.reviewFilter==='all'}" @click="selectAll"><span>全部记录</span><b>{{ assessments.loading ? '…' : assessments.total }}</b></button><p v-if="assessments.hasMore" class="sidebar-scope-note">以下按已加载的 {{ assessments.records.length }} 份记录筛选，可加载更多。</p><section class="sidebar-filter-group"><h2>按日期</h2><div class="sidebar-date-list"><button v-for="item in dates" :key="item.date" class="sidebar-filter" :class="{active:assessments.dateFilter===item.date}" @click="assessments.dateFilter=item.date"><span>{{ item.date }}</span><small>{{ item.count }} 份</small></button><p v-if="!dates.length" class="sidebar-filter-empty">暂无记录</p></div></section><section class="sidebar-filter-group sidebar-filter-group--status"><h2>查看状态</h2><button v-for="item in [{value:'all',label:'全部',tone:'neutral'},{value:'pending',label:'待查看',tone:'pending'},{value:'viewed',label:'已查看',tone:'viewed'}]" :key="item.value" class="sidebar-filter sidebar-filter--status" :class="[{active:assessments.reviewFilter===item.value},`is-${item.tone}`]" @click="assessments.reviewFilter=item.value as 'all'|'pending'|'viewed'"><i></i><span>{{ item.label }}</span><b>{{ statusCount(item.value as 'all'|'pending'|'viewed') }}</b></button></section></section></template><div class="sidebar__footer"><button class="text-button" @click="logout">退出登录</button></div></aside><main class="admin-main"><slot /></main></div></template>

<style scoped>
.sidebar-scope-note{margin:-12px 10px 0;color:#617384;font-size:12px;line-height:1.6}.sidebar-filters{display:grid;gap:22px;min-height:0;margin-top:16px}.sidebar-filter-group{display:grid;gap:10px}.sidebar-filter-group h2{margin:0 10px;color:#94a2ae;font-size:12px;font-weight:650}.sidebar-date-list{display:grid;gap:6px;max-height:350px;overflow:auto;padding:1px 2px 3px}.sidebar-filter{display:flex;align-items:center;justify-content:space-between;width:100%;border:0;border-left:2px solid transparent;border-radius:8px;padding:10px 11px;color:#617384;background:transparent;text-align:left;font-size:14px;cursor:pointer}.sidebar-filter small{display:block;margin-top:3px;color:#9aa8b4;font-size:11px}.sidebar-filter b{font-size:11px;font-weight:650}.sidebar-filter:hover{background:#f6faf9}.sidebar-filter.active{border-left-color:#2d9e83;color:#227863;background:#ebf8f4;font-weight:650}.sidebar-filter.active small{color:#478f7d}.sidebar-filter--all{margin:0 0 4px;padding:11px 12px;font-size:14px}.sidebar-filter-group--status{gap:7px;padding-top:20px;border-top:1px solid #edf1f0}.sidebar-filter--status{gap:8px;padding:8px 11px;font-size:13px}.sidebar-filter--status i{width:6px;height:6px;border-radius:50%;background:#9ca9b5}.sidebar-filter--status span{flex:1}.sidebar-filter--status.is-pending i{background:#d6a038}.sidebar-filter--status.is-viewed i{background:#22a978}.sidebar-filter-empty{margin:8px;color:#9aa8b4;font-size:12px}
</style>
